p.setup = function() {
  p.createCanvas(p.windowWidth, p.windowHeight, p.WEBGL);
  p.pixelDensity(2);
};
p.windowResized = function() {
  p.resizeCanvas(p.windowWidth, p.windowHeight);
};
p.draw = function() {
  p.background(0);
  p.orbitControl();
  p.rotateY(p.frameCount * 0.01);
  p.stroke(0, 255, 255);
  p.noFill();
  let spacing = 20;
  let radius = Math.min(p.width, p.height) / 8;
  let helixHeight = Math.min(p.height, p.width) / 1.5;
  p.beginShape();
  for (let i = -helixHeight; i < helixHeight; i += spacing) {
    let angle = i * 0.1 + p.frameCount * 0.05;
    let x = radius * p.cos(angle);
    let y = i;
    let z = radius * p.sin(angle);
    p.vertex(x, y, z);
  }
  p.endShape();
  p.stroke(255, 0, 255);
  p.beginShape();
  for (let i = -helixHeight; i < helixHeight; i += spacing) {
    let angle = i * 0.1 + p.frameCount * 0.05 + p.PI;
    let x = radius * p.cos(angle);
    let y = i;
    let z = radius * p.sin(angle);
    p.vertex(x, y, z);
  }
  p.endShape();
  p.stroke(255);
  for (let i = -helixHeight; i < helixHeight; i += spacing) {
    let angle1 = i * 0.1 + p.frameCount * 0.05;
    let angle2 = angle1 + p.PI;
    let x1 = radius * p.cos(angle1);
    let z1 = radius * p.sin(angle1);
    let x2 = radius * p.cos(angle2);
    let z2 = radius * p.sin(angle2);
    p.line(x1, i, z1, x2, i, z2);
  }
};
